-- Esquema MySQL de GrowLab. El backend también lo aplica automáticamente al iniciar.
-- Crear primero la base: CREATE DATABASE growlab CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS categorias (slug VARCHAR(80) PRIMARY KEY, nombre VARCHAR(150) NOT NULL, icono VARCHAR(80) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS productos (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(120) UNIQUE NOT NULL, nombre VARCHAR(180) NOT NULL, categoria VARCHAR(80) NOT NULL, precio INT NULL, stock INT NOT NULL DEFAULT 0, etiqueta VARCHAR(80) NOT NULL DEFAULT '', descripcion TEXT NOT NULL, imagen VARCHAR(80) NOT NULL DEFAULT 'kit', destacado TINYINT(1) NOT NULL DEFAULT 0, activo TINYINT(1) NOT NULL DEFAULT 1, regulado TINYINT(1) NOT NULL DEFAULT 0, creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (categoria) REFERENCES categorias(slug), CHECK (stock >= 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX idx_productos_categoria ON productos(categoria, activo);
CREATE TABLE IF NOT EXISTS pedidos (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, codigo VARCHAR(40) UNIQUE NOT NULL, idempotencia VARCHAR(100) UNIQUE NULL, nombre VARCHAR(120) NOT NULL, email VARCHAR(200) NOT NULL, telefono VARCHAR(40) NOT NULL, provincia VARCHAR(80) NOT NULL, direccion VARCHAR(300) NOT NULL, observaciones VARCHAR(600) NOT NULL DEFAULT '', subtotal INT NOT NULL, estado VARCHAR(30) NOT NULL DEFAULT 'pendiente', estado_pago VARCHAR(30) NOT NULL DEFAULT 'pendiente', creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS pedido_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, pedido_id INT UNSIGNED NOT NULL, producto_id INT UNSIGNED NOT NULL, nombre VARCHAR(180) NOT NULL, precio INT NOT NULL, cantidad INT NOT NULL, subtotal INT NOT NULL, FOREIGN KEY (pedido_id) REFERENCES pedidos(id), FOREIGN KEY (producto_id) REFERENCES productos(id), CHECK (cantidad > 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX idx_pedido_items_pedido ON pedido_items(pedido_id);
CREATE TABLE IF NOT EXISTS notas (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, titulo VARCHAR(120) NOT NULL, contenido TEXT NOT NULL, creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
